(()=>{'use strict';
 const S=window.TitaniumStore,root=document.getElementById('portal-root'),dialog=document.getElementById('portal-dialog'),toastEl=document.getElementById('portal-toast');
 if(!root)return;
 const esc=s=>String(s??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#39;');
 const icons={grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',book:'<path d="M12 5v16M3 4c4-1 7 0 9 2 2-2 5-3 9-2v15c-4-1-7 0-9 2-2-2-5-3-9-2Z"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M2 20v-2a7 7 0 0 1 14 0v2m0-15a3 3 0 0 1 0 6m3 9v-2a6 6 0 0 0-2-5"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 11h18m-12 4h2m4 0h2"/>',award:'<circle cx="12" cy="8" r="5"/><path d="m8 12-2 10 6-3 6 3-2-10"/>',layers:'<path d="m12 3 10 6-10 6L2 9Zm-10 12 10 6 10-6M2 12l10 6 10-6"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',spark:'<path d="m12 3 3 6 6 3-6 3-3 6-3-6-6-3 6-3Z"/>',chat:'<path d="M21 11a9 9 0 0 1-9 9H3l2-5a9 9 0 1 1 16-4Z"/>',search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',briefcase:'<rect x="3" y="7" width="18" height="14" rx="2"/><path d="M8 7V3h8v4M3 12l9 3 9-3"/>',check:'<path d="m5 12 4 4L19 6"/>',logout:'<path d="M9 4H3v16h6m5-15 7 7-7 7M8 12h13"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>'};
 const icon=n=>`<svg class="p-icon" aria-hidden="true" viewBox="0 0 24 24">${icons[n]||icons.book}</svg>`;
 const btn=(label,action='',extra='',style='')=>`<button class="p-btn ${style}" type="button" data-action="${action}" ${extra}>${label}</button>`;
 const go=(label,href,style='')=>`<a class="p-btn ${style}" href="${href}">${label}</a>`;
 const status=s=>`<span class="p-status ${esc(s)}">${esc(s)}</span>`;
 const name=(type,id)=>{const r=S.db[type].find(x=>x.id===id);return r?.name||r?.title||'—'};
 const initials=s=>String(s||'?').split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase();
 const avatar=u=>`<span class="p-avatar">${esc(initials(u?.name))}</span>`;
 const fmtDate=s=>s?new Date(s.length===10?s+'T12:00:00':s).toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'}):'—';
 const money=i=>new Intl.NumberFormat('en').format(Math.round(i.price*(1-i.discount/100)))+' '+i.currency;
 const myRequests=()=>S.db.enrollments.filter(e=>e.userId===S.user()?.id);
 const teacher=()=>S.db.teachers.find(t=>t.userId===S.user()?.id);
 const assigned=()=>S.db.instances.filter(i=>i.teacherId===teacher()?.id);
 const profileKeys=['name','phone','college','department','graduation','sector','position','seniority','interests','about'];
 const completeness=()=>Math.round(profileKeys.filter(k=>S.user()?.[k]).length/profileKeys.length*100);
 const safeHref=s=>{try{return ['https:','http:'].includes(new URL(s).protocol)?esc(s):''}catch{return ''}};
 const preview=`<div class="p-preview"><strong>Local prototype</strong> · Changes stay in this browser. Accounts, cohorts, prices and requests are sample data. No payments or messages are sent.</div>`;
 let current='',query='',filter='',timer,modalReturn;
 function toast(message){clearTimeout(timer);toastEl.textContent=message;toastEl.hidden=false;timer=setTimeout(()=>toastEl.hidden=true,4200)}
 function empty(title,text,action=''){return `<div class="p-empty">${icon('book')}<h3>${title}</h3><p>${text}</p>${action}</div>`}
 function heading(title,desc,actions=''){return `<div class="p-heading"><div><span class="p-context">Titanium / ${S.user()?.role||'Learning workspace'}</span><h1 tabindex="-1">${title}</h1><p>${desc}</p></div>${actions?`<div class="p-heading-actions">${actions}</div>`:''}</div>`}
 function panel(title,body,link=''){return `<section class="p-panel"><div class="p-panel-head"><h2>${title}</h2>${link}</div>${body}</section>`}
 function settingsPage(){const admin=S.user()?.role==='Admin';return heading('Settings.','Manage how your Titanium account works for you.')+`<div class="p-placeholder">${icon('grid')}<span class="p-future">Coming soon</span><strong>Your account settings will live here.</strong><p>Account preferences will be added to this page. For now, you can update your name, contact details and learning interests in your profile.</p>${go('Go to my profile',admin?'workspace.html#admin/profile':'profile.html','secondary')}</div>`}
 function placeholder(type){if(type==='recommendations')return recommendations(true);const recommend=false;return `<div class="p-placeholder">${icon(recommend?'spark':'bell')}<span class="p-future">Planned feature</span><strong>${recommend?'A learning path that fits you.':'Your updates, in one place.'}</strong><p>${recommend?'Personalized course recommendations will appear here when the recommendation system is connected. You can explore the catalog today.':'Enrollment and course updates will appear here when notifications are connected. Check My courses for request decisions today.'}</p></div>`}
 const adminNav=[['admin','Overview','grid'],['admin/requests','Enrollment requests','users'],['admin/courses','Courses','book'],['admin/instances','Course instances','calendar'],['admin/categories','Course categories','layers'],['admin/vendors','Course vendors','briefcase'],['admin/certificates','Certificates','award'],['admin/certificateCategories','Certificate categories','layers'],['admin/teachers','Teachers','users'],['admin/users','Users','user']];
 const adminFolders=[{id:'courses-folder',name:'Courses',hasChildren:true,icon:icon('book')},{id:'certificates-folder',name:'Certificates',hasChildren:true,icon:icon('award')}];
 const folderChildren={'courses-folder':[['admin/courses','All courses'],['admin/instances','Course instances'],['admin/categories','Course categories'],['admin/vendors','Course vendors']],'certificates-folder':[['admin/certificates','All certificates'],['admin/certificateCategories','Certificate categories']]};
 let treeCleanup;function adminTree(){treeCleanup?.();const container=document.getElementById('admin-folder-tree');if(!container)return;const selected=current.startsWith('admin/user/')?'admin/users':current.startsWith('admin/course/')?'admin/courses':current;let expanded=[];try{expanded=JSON.parse(sessionStorage.getItem('titanium-admin-folders')||'[]');if(!Array.isArray(expanded))expanded=[]}catch{}for(const [id,children]of Object.entries(folderChildren))if(children.some(([route])=>route===selected)&&!expanded.includes(id))expanded.push(id);const leaf=(id,name)=>({id,name,hasChildren:false,icon:icon({'admin':'grid','admin/requests':'calendar','admin/teachers':'users','admin/users':'user'}[id]||'book')});treeCleanup=window.TitaniumFolderTree?.mount(container,{nodes:[leaf('admin','Overview'),leaf('admin/requests','Enrollment requests'),...adminFolders,leaf('admin/teachers','Teachers'),leaf('admin/users','Users')],selectedId:selected,expandedIds:expanded,loadChildren:async node=>(folderChildren[node.id]||[]).map(([id,name])=>leaf(id,name)),onExpandedIdsChange:ids=>{try{sessionStorage.setItem('titanium-admin-folders',JSON.stringify(ids))}catch{}},onSelect:node=>{location.href='workspace.html#'+node.id}})}
 function shell(content){const u=S.user(),admin=u?.role==='Admin';if(!admin)return '<div class="member-content">'+preview+content+'</div>';const links=adminNav;
 return `<div class="p-shell"><aside class="p-sidebar" aria-label="Titanium administration"><button type="button" class="p-sidebar-collapse" data-sidebar-collapse aria-label="Collapse sidebar" aria-expanded="true"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m14 7-5 5 5 5"/></svg></button><div class="p-sidebar-head"><div class="p-mobile-nav"><strong>Titanium Admin</strong><button class="p-btn secondary small p-burger-btn" type="button" data-action="menu" aria-expanded="false" aria-controls="admin-navigation" aria-label="Menu"><span class="p-burger" aria-hidden="true"><span></span><span></span><span></span></span></button></div><div class="p-admin-identity">${avatar(u)}<div class="p-admin-identity-text"><span class="p-workmark">Titanium Admin</span><strong>${esc(u.name)}</strong><span class="p-side-caption">Training center workspace</span></div></div></div><nav class="p-side-links" id="admin-navigation" aria-label="Workspace navigation"><span class="p-nav-label">Main</span><ul class="p-folder-tree" id="admin-folder-tree" aria-label="Admin sections"></ul><span class="p-nav-label p-account-divider">Account</span><a class="p-profile-link" data-sidebar-label="My profile" href="workspace.html#admin/profile"${['admin/profile','profile','notifications'].includes(current)?' aria-current="page"':''}>${icon('user')}<span>My profile</span></a></nav><div class="p-sidebar-footer"><a class="p-sidebar-footer-link p-back-website" data-sidebar-label="Back to website" href="index.html">${icon('arrow')}<span>Back to website</span></a><button class="p-signout" data-action="logout" data-sidebar-label="Sign out">${icon('logout')}<span>Sign out</span></button></div></aside><div class="p-main">${preview}${content}</div></div>`}

 function auth(signup=false){return `<a class="p-auth-back" href="index.html">${icon('arrow')}<span>Back to home</span></a><div class="p-auth"><div class="p-auth-story"><span class="p-context">Titanium Training Center</span><h1>Your next chapter<br>starts with you.</h1><p>Keep your learning, course requests and profile together in your Titanium account.</p>${[['01','Find the right course'],['02','Request your place'],['03','Keep moving forward']].map(([n,t])=>`<div class="p-auth-number"><span>${n}</span><strong>${t}</strong></div>`).join('')}<div class="p-note">Local prototype. Use sample details, not a real password or sensitive personal information. Demo role access is available for reviewing the interface.</div></div><div class="p-auth-card"><h2>${signup?'Create your account.':'Welcome back.'}</h2><p>${signup?'Start with the essentials. Complete the rest of your profile later.':'Sign in to continue your learning journey.'}</p><form id="auth-form" data-mode="${signup?'signup':'login'}"><div class="p-fields">${signup?field('name','Full name','text','',true)+field('phone','Phone number','tel','',true):''}${field('email','Email address','email','',true)}${field('password','Password','password','',true,'At least 8 characters. Use a sample password for this local prototype.')}${signup?field('confirmPassword','Confirm password','password','',true):''}</div><p class="p-error" id="auth-error" role="alert" hidden></p><button class="p-btn" type="submit">${signup?'Create account':'Sign in'} ${icon('arrow')}</button></form><p class="p-auth-switch">${signup?'Already have an account? <a href="#login">Sign in</a>':'New to Titanium? <a href="#signup">Create an account</a>'}</p><div class="p-demo"><p><strong>Explore a demo account</strong><br>Review each role without creating an account.</p><div class="p-demo-roles">${['Student','Teacher','Admin'].map(r=>`<button data-action="demo" data-role="${r}">${r} demo</button>`).join('')}</div></div></div></div>`}
 function field(key,label,type='text',value='',required=false,hint='',options){const id='p-'+key,attrs=`id="${id}" name="${key}"${required?' required':''}`;let input;if(type==='select')input=`<select ${attrs}><option value="">Choose…</option>${options.map(o=>{const [v,t]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}"${String(value)===String(v)?' selected':''}>${esc(t)}</option>`}).join('')}</select>`;else if(type==='textarea')input=`<textarea ${attrs} rows="3" maxlength="1800">${esc(value)}</textarea>`;else if(type==='checkbox')input=`<input ${attrs} type="checkbox" role="switch"${value?' checked':''}>`;else input=`<input ${attrs} type="${type}" value="${type==='password'?'':esc(value)}"${type==='password'?' minlength="8" maxlength="128" autocomplete="new-password"':type==='number'?' min="0" max="2147483647" step="1"':' maxlength="500"'}${hint?` aria-describedby="${id}-hint"`:''}>`;return `<div class="p-field${type==='textarea'?' full':''}${type==='checkbox'?' check':''}">${type==='checkbox'?input:''}<label for="${id}">${label}${required?' <span aria-hidden="true">*</span>':''}</label>${type==='checkbox'?'':input}${hint?`<small id="${id}-hint">${hint}</small>`:''}</div>`}
 function stats(items){return `<div class="p-stats">${items.map(([label,value,detail])=>`<div class="p-stat"><span>${label}</span><strong>${value}</strong><small>${detail}</small></div>`).join('')}</div>`}
 function enrollmentLine(e){const i=S.db.instances.find(x=>x.id===e.instanceId);return `<div class="p-line-item">${icon('book')}<div><strong>${esc(name('courses',i?.courseId))}</strong><p>${esc(i?.name)} · ${fmtDate(i?.date)}</p></div>${status(e.status)}</div>`}
 function courseCard(c){const favorite=S.db.favorites.some(f=>f.userId===S.user()?.id&&f.courseId===c.id),instances=S.db.instances.filter(i=>i.courseId===c.id&&i.active&&!i.private),open=instances.filter(i=>i.status==='Open').length,t=S.db.teachers.find(t=>t.active&&t.id===instances[0]?.teacherId);return `<article class="p-course has-thumb"><div class="p-course-thumb" data-cover-mark="${esc(S.mark(c.id))}">${S.media.poster(c,S.mark(c.id))}</div><div class="p-course-top"><span class="p-chip">${esc(name('categories',c.categoryId))}</span>${['Student','Teacher'].includes(S.user()?.role)?`<button class="p-heart" data-action="favorite" data-id="${esc(c.id)}" aria-pressed="${favorite}" aria-label="${favorite?'Unsave':'Save'} ${esc(c.title)}">${icon('heart')}</button>`:''}</div><div class="p-course-mark">${S.mark(c.id)||icon('book')}</div><h2>${esc(c.title)}</h2><p>${esc(c.description)}</p>${t?`<a class="p-teacher-link" href="#teacher/${esc(t.id)}">${avatar(t)}<span><small>Demo cohort instructor</small><strong>${esc(t.name)}</strong></span>${icon('arrow')}</a>`:'<span class="p-quiet">Instructor to be assigned</span>'}<div class="p-course-meta"><span>${esc(c.difficulty)}</span><span>${c.lectures} lectures</span><span>${esc(c.language)}</span></div><div class="p-course-end"><small>${esc(name('vendors',c.vendorId))}<br>${open?'Open cohorts available':'Explore upcoming availability'}</small><a class="p-link" href="#course/${esc(c.id)}">Explore course →</a></div></article>`}
 function recommendations(compact=false){let ids=[];try{ids=JSON.parse(sessionStorage.getItem('titanium-demo-recommendations')||'[]');if(!Array.isArray(ids))ids=[]}catch{}const active=S.db.courses.filter(c=>c.active),shuffled=[...active];for(let i=shuffled.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[shuffled[i],shuffled[j]]=[shuffled[j],shuffled[i]]}const ordered=[...new Set([...ids,...shuffled.map(c=>c.id)])].map(id=>active.find(c=>c.id===id)).filter(Boolean).slice(0,3);try{sessionStorage.setItem('titanium-demo-recommendations',JSON.stringify(ordered.map(c=>c.id)))}catch{}if(!ordered.length)return empty('More learning is on its way.','Active courses will appear here when they are added to the catalog.');return compact?'<div class="p-recommendation-list">'+ordered.map(c=>`<a class="p-line-item" href="#course/${esc(c.id)}"><span class="p-course-mark">${S.mark(c.id)||icon('book')}</span><div><strong>${esc(c.title)}</strong><p>${esc(name('categories',c.categoryId))}</p></div>${icon('arrow')}</a>`).join('')+'</div>':'<div class="p-catalog p-recommendations">'+ordered.map(courseCard).join('')+'</div>'}
 function catalog(saved=false){const rows=S.db.courses.filter(c=>c.active&&(!saved||S.db.favorites.some(f=>f.userId===S.user()?.id&&f.courseId===c.id)));return heading(saved?'Your learning shortlist.':'Find your next step.',saved?'The courses you have saved, ready when you are.':'Explore programs and request a place in a specific course instance.')+toolbar(saved?'Search saved courses':'Search courses',S.db.categories.filter(c=>c.active).map(c=>[c.id,c.name]),'All categories')+`<div class="p-catalog" id="p-records">${rows.map(c=>`<div class="p-searchable" data-search="${esc(c.title+' '+name('vendors',c.vendorId))}" data-filter="${esc(c.categoryId)}">${courseCard(c)}</div>`).join('')}</div><div id="p-no-results" hidden>${empty(saved?'No saved courses here yet.':'No courses found.',saved?'Save a course using the heart in the course catalog.':'Try another search or category.',go('Explore catalog','#catalog','secondary'))}</div>`}
 function toolbar(label,options=[],all='All statuses'){return `<div class="p-toolbar"><label class="p-search">${icon('search')}<input id="p-search" type="search" placeholder="${label}" aria-label="${label}" value="${esc(query)}"></label>${options.length?`<select id="p-filter" aria-label="Filter records"><option value="">${all}</option>${options.map(([v,t])=>`<option value="${esc(v)}"${filter===v?' selected':''}>${esc(t)}</option>`).join('')}</select>`:''}<span class="p-quiet" id="p-count" role="status"></span></div>`}
 function courseDetail(id){const c=S.db.courses.find(c=>c.id===id&&c.active);if(!c)return heading('Course unavailable.','This course may have been archived.',go('Back to catalog','#catalog','secondary'));const isAdmin=S.user()?.role==='Admin',instances=S.db.instances.filter(i=>i.courseId===id&&i.active&&(!i.private||isAdmin));return heading(esc(c.title),esc(c.description),go('All courses','#catalog','secondary'))+`<div class="p-detail-grid"><div>${S.media.player(c,S.mark(c.id))||(S.media.imageURL(c.thumbnail)?`<div class="p-detail-thumb">${S.media.poster(c)}</div>`:'')}${panel('About this program',`<span class="p-chip">${esc(name('categories',c.categoryId))}</span><dl class="p-facts">${[['Difficulty',c.difficulty],['Language',c.language],['Lectures',c.lectures],['Vendor',name('vendors',c.vendorId)],['Certificate',name('certificates',c.certificateId)]].map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl>${c.publicPage?`<a class="p-link" href="${esc(c.publicPage)}">Read the full program overview →</a>`:''}`)}<div class="p-note">Choose a cohort to request enrollment. The admin reviews your request; submitting it does not reserve a place. No payment is required in this prototype.</div></div><section><h2>Available course instances</h2><p>Sample dates, fees and assignments for reviewing the flow.</p>${instances.map(instanceCard).join('')||empty('No cohorts listed yet.','Check back for a new instance or ask the Titanium team.')}</section></div>`}
 function instanceCard(i){const e=myRequests().find(e=>e.instanceId===i.id),t=S.db.teachers.find(t=>t.id===i.teacherId),seats=i.capacity-S.db.enrollments.filter(e=>e.instanceId===i.id&&e.status==='Approved').length;return `<article class="p-session"><div class="p-panel-head"><h3>${esc(i.name)}</h3>${status(i.status)}</div><p>${fmtDate(i.date)} · ${esc(i.duration)}<br>${esc(i.days)}</p><p>Instructor: ${t?`<a href="#teacher/${esc(t.id)}">${esc(t.name)}</a>`:'To be assigned'}<br>${seats} of ${i.capacity} places available${i.private?' · Private cohort':''}</p><div class="p-session-bottom"><div class="p-price"><strong>${money(i)}</strong><small>Sample price${i.discount?' · '+i.discount+'% discount':''}</small></div>${e?status(e.status):['Student','Teacher'].includes(S.user()?.role)?btn(i.status==='Open'&&seats>0?'Request to join':seats===0?'Cohort full':'Not open yet','request',`data-id="${esc(i.id)}"${i.status!=='Open'||seats<1?' disabled':''}`):'<span class="p-quiet">Student enrollment only</span>'}</div>${e?.status==='Rejected'?`<div class="p-request-reason">${esc(e.reason)}</div>`:''}</article>`}
 function myCourses(){const selected=location.hash.split('?')[1]?.replace('status=','')||'all',es=myRequests().filter(e=>selected==='all'||e.status===selected);return heading('Your courses, your progress.','Track the courses you joined and every request along the way.',go('Explore courses','#catalog'))+`<nav class="p-tabs" aria-label="Enrollment status">${[['all','All courses'],['Approved','Joined'],['Pending','Pending'],['Rejected','Rejected']].map(([v,t])=>`<a href="#my-courses?status=${v}"${selected===v?' aria-current="page"':''}>${t} (${myRequests().filter(e=>v==='all'||e.status===v).length})</a>`).join('')}<a href="#favorites">Saved courses</a></nav><div class="p-catalog">${es.map(e=>{const i=S.db.instances.find(x=>x.id===e.instanceId);return `<article class="p-course"><div class="p-course-top">${status(e.status)}<small class="p-quiet">Requested ${fmtDate(e.created)}</small></div><h2>${esc(name('courses',i?.courseId))}</h2><p>${esc(i?.name)}<br>${fmtDate(i?.date)} · ${esc(i?.days)}</p>${e.reason?`<div class="p-request-reason">${esc(e.reason)}</div>`:''}<div class="p-course-end"><small>${e.status==='Pending'?'The admin is reviewing your request.':e.status==='Approved'?'Your place is approved.':'Your request was not approved.'}</small><a class="p-link" href="#course/${esc(i?.courseId)}">View cohort →</a></div></article>`}).join('')||empty('No courses in this view.','Browse open cohorts to take your next step.',go('Browse courses','#catalog'))}</div>`}
 function profile(){const u=S.user();return heading('Make your profile yours.','Start with what matters now. Add more details whenever you are ready.')+`<section class="p-panel"><div class="p-profile-header"><span class="p-avatar large">${esc(initials(u.name))}</span><div><h2>${esc(u.name)}</h2><p>${esc(u.email)} · ${u.role}</p><span class="p-quiet">Joined ${fmtDate(u.created)}</span></div></div><div class="p-progress" role="progressbar" aria-label="Profile completion" aria-valuenow="${completeness()}" aria-valuemin="0" aria-valuemax="100"><span style="width:${completeness()}%"></span></div><p>${completeness()}% complete · Extra profile details are optional. This is profile completion, not identity verification.</p><form id="profile-form"><div class="p-form-section"><h3>The essentials</h3><p>Your signup details and personal introduction.</p></div><div class="p-fields">${field('name','Full name','text',u.name,true)}${field('phone','Phone number','tel',u.phone)}<div class="p-field"><label for="p-account-email">Email address</label><input id="p-account-email" type="email" value="${esc(u.email)}" disabled><small>Contact an administrator to change your account email.</small></div>${field('profilePic','Profile photo URL','url',u.profilePic,false,'Saved as a profile reference. This prototype uses initials as your avatar.')}${field('about','About you','textarea',u.about)}</div><div class="p-form-section"><h3>Education</h3><p>Add your college and current academic stage.</p></div><div class="p-fields">${field('college','College / university','text',u.college)}${field('department','Department','text',u.department)}${field('graduation','Graduation status','select',u.graduation,false,'',['Studying','Graduated','Not applicable'])}</div><div class="p-form-section"><h3>Work & learning interests</h3><p>These fields are provisional and can be adjusted to your final KYC requirements.</p></div><div class="p-fields">${field('sector','Company sector','text',u.sector)}${field('position','Position','text',u.position)}${field('seniority','Seniority','select',u.seniority,false,'',['Student','Entry level','Mid level','Senior','Lead / Manager','Not applicable'])}${field('cv','CV link','url',u.cv,false,'Optional link; no documents are uploaded.')}${field('interests','Learning interests','textarea',u.interests)}</div><p class="p-error" id="profile-error" role="alert" hidden></p><div class="p-form-actions"><button class="p-btn" type="submit">Save profile</button></div></form></section>`}
 function teaching(){const rows=assigned();return heading('Ready for your next session.','Your assigned course instances and approved student rosters.')+rows.map(i=>{const es=S.db.enrollments.filter(e=>e.instanceId===i.id&&e.status==='Approved');return panel(esc(name('courses',i.courseId)),`<p>${esc(i.name)} · ${fmtDate(i.date)} · ${esc(i.days)}</p><div class="p-panel-head">${status(i.status)}<span class="p-quiet">${es.length} / ${i.capacity} enrolled</span></div>${es.length?table(['Learner','Email','Enrollment'],es.map(e=>{const u=S.db.users.find(u=>u.id===e.userId);return `<tr><td><strong>${esc(u?.name)}</strong></td><td>${esc(u?.email)}</td><td>${status('Approved')}</td></tr>`})):empty('Your roster is waiting.','Approved students will appear here after an admin reviews their requests.')}`)}).join('')||heading('No assigned cohorts.','An admin can assign a teacher in Course instances.')}
 function teacherProfile(id){const t=S.db.teachers.find(t=>t.id===id&&t.active);if(!t)return heading('Teacher unavailable.','This profile is not currently active.');return heading(esc(t.name),esc(t.title),go('Course catalog','#catalog','secondary'))+`<div class="p-detail-grid">${panel('About your instructor',`<span class="p-avatar large">${esc(initials(t.name))}</span><p style="margin-top:20px">${esc(t.bio)}</p><dl class="p-facts"><div><dt>Teaching focus</dt><dd>${esc(t.focus)}</dd></div><div><dt>Credentials</dt><dd>${esc(t.credentials||'Ask the center for details.')}</dd></div></dl>${t.publicPage?`<a class="p-link" href="${esc(t.publicPage)}">Full instructor profile →</a>`:''}`)}<div><h2>Course instances</h2>${S.db.instances.filter(i=>i.teacherId===id&&i.active&&!i.private&&S.db.courses.some(c=>c.id===i.courseId&&c.active)).map(i=>`<div class="p-panel"><h3>${esc(name('courses',i.courseId))}</h3><p>${esc(i.name)} · ${fmtDate(i.date)}</p><a class="p-link" href="#course/${esc(i.courseId)}">Explore course →</a></div>`).join('')||empty('No public cohorts listed.','Contact the center about upcoming teaching.')}</div></div>`}
 function table(heads,rows){const lab=r=>{let i=0;return r.replace(/<td>/g,()=>`<td data-label="${String(heads[i++]||'').replace(/"/g,'&quot;')}">`)};return `<div class="p-table-wrap"><table class="p-table"><thead><tr>${heads.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody id="p-records">${rows.map(lab).join('')}</tbody></table></div>`}
 const configs={
  courses:{label:'Courses',singular:'course',desc:'The core program, independent of its scheduled cohorts.',columns:['Course','Category / vendor','Details','Status','Actions'],fields:[['title','Course title','text',true],['short','Short name','text',true],['description','Description','textarea'],['lectures','Lecture count','number',true],['categoryId','Course category','categories'],['vendorId','Vendor','vendors'],['certificateId','Certificate','certificates'],['difficulty','Difficulty','select',false,['Beginner','Intermediate','Advanced']],['language','Language','select',false,['English','Arabic','English & Arabic']],['video','Video URL','url'],['thumbnail','Thumbnail URL','url'],['active','Active','checkbox']]},
  instances:{label:'Course instances',singular:'course instance',desc:'Schedule, assign an instructor and manage availability for each cohort.',columns:['Cohort / course','Schedule','Seats / sample price','Status','Actions'],fields:[['name','Cohort name','text',true],['courseId','Course','courses',true],['teacherId','Teacher','teachers'],['date','Start date','date',true],['duration','Duration label','text',true],['days','Program days / times','text'],['capacity','Seat capacity','number',true],['price','Price (display only)','number',true],['discount','Discount percent','number'],['currency','Currency','select',true,['IQD','USD']],['status','Instance status','select',true,['Open','Upcoming','Closed','Completed','Cancelled']],['private','Private cohort','checkbox'],['active','Active','checkbox']]},
  categories:{label:'Course categories',singular:'course category',desc:'Organize programs into clear learning areas.',columns:['Category','Description','Status','Actions'],fields:[['name','Category name','text',true],['description','Description','textarea'],['active','Active','checkbox']]},
  vendors:{label:'Course vendors',singular:'vendor',desc:'Maintain the organizations associated with your courses and certificates.',columns:['Vendor','Website','Status','Actions'],fields:[['name','Vendor name','text',true],['website','Website','url'],['logo','Logo URL','url'],['active','Active','checkbox']]},
  certificates:{label:'Certificates',singular:'certificate',desc:'Manage certificate definitions and their vendor and category. Student certificate issuance is outside this prototype.',columns:['Certificate','Category','Vendor','Status','Actions'],fields:[['name','Certificate name','text',true],['categoryId','Certificate category','certificateCategories',true],['vendorId','Vendor','vendors'],['logo','Certificate logo URL','url'],['active','Active','checkbox']]},
  certificateCategories:{label:'Certificate categories',singular:'certificate category',desc:'Group the certificate types offered by your center.',columns:['Category','Description','Status','Actions'],fields:[['name','Category name','text',true],['description','Description','textarea'],['active','Active','checkbox']]},
  teachers:{label:'Teachers',singular:'teacher profile',desc:'Link teaching profiles to accounts with the Teacher role, then assign them to cohorts.',columns:['Teacher','Account / focus','Status','Actions'],fields:[['name','Display name','text',true],['userId','Teacher account','teacherUsers',true],['title','Professional title','text',true],['bio','Biography','textarea'],['credentials','Credentials','text'],['focus','Teaching focus','textarea'],['active','Active','checkbox']]},
  users:{label:'Users',singular:'user',desc:'Manage Student, Teacher and Admin accounts and view their profile details.',columns:['User','Role','Profile','Status','Actions'],fields:[['name','Full name','text',true],['email','Email address','email',true],['phone','Phone number','tel'],['role','Role','select',true,['Student','Teacher','Admin']],['password','Initial / replacement password','password'],['active','Active','checkbox']]}
 };
 function recordRow(type,r){let cells=[];if(type==='courses')cells=[`<strong>${esc(r.title)}</strong><small>${esc(r.short)}</small>`,`${esc(name('categories',r.categoryId))}<small>${esc(name('vendors',r.vendorId))}</small>`,`${r.lectures} lectures<small>${esc(r.difficulty)} · ${esc(r.language)}</small>`];else if(type==='instances')cells=[`<strong>${esc(r.name)}</strong><small>${esc(name('courses',r.courseId))}</small>`,`${fmtDate(r.date)}<small>${esc(name('teachers',r.teacherId))} · ${esc(r.duration)}</small>`,`${S.db.enrollments.filter(e=>e.instanceId===r.id&&e.status==='Approved').length} / ${r.capacity} seats<small>${money(r)}</small>`];else if(type==='certificates')cells=[`<strong>${esc(r.name)}</strong>`,esc(name('certificateCategories',r.categoryId)),esc(name('vendors',r.vendorId))];else if(type==='vendors')cells=[`<strong>${esc(r.name)}</strong>`,safeHref(r.website)?`<a href="${safeHref(r.website)}" target="_blank" rel="noopener noreferrer">Visit website ↗</a>`:'—'];else if(type==='teachers')cells=[`<strong>${esc(r.name)}</strong><small>${esc(r.title)}</small>`,`${esc(S.db.users.find(u=>u.id===r.userId)?.email)}<small>${esc(r.focus)}</small>`];else if(type==='users')cells=[`<strong>${esc(r.name)}</strong><small>${esc(r.email)}</small>`,status(r.role),`<a class="p-link" href="#admin/user/${esc(r.id)}">View details →</a>${r.demo?'<small>Demo account</small>':''}`];else cells=[`<strong>${esc(r.name)}</strong>`,esc(r.description||'—')];cells.push(status(r.active?(type==='instances'?r.status:'Active'):'Inactive'));cells.push(`<div class="p-row-actions"><button class="p-icon-btn" data-action="view" data-type="${type}" data-id="${esc(r.id)}" aria-label="View ${esc(r.name||r.title||'')}" data-tip="View"><svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M2 12s3.6-7 10-7 10 7 10 7-3.6 7-10 7S2 12 2 12z"/><circle cx="12" cy="12" r="3"/></svg></button><button class="p-icon-btn" data-action="edit" data-type="${type}" data-id="${esc(r.id)}" aria-label="Edit ${esc(r.name||r.title||'')}" data-tip="Edit"><svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M12 20h9"/><path d="M16.5 3.5a2.1 2.1 0 0 1 3 3L7 19l-4 1 1-4z"/></svg></button><button class="p-icon-btn p-delete" data-action="delete" data-type="${type}" data-id="${esc(r.id)}" aria-label="Delete ${esc(r.name||r.title||'')}" data-tip="Delete"><svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M3 6h18"/><path d="M8 6V4h8v2"/><path d="M19 6l-1 14H6L5 6"/><path d="M10 11v6M14 11v6"/></svg></button></div>`);return `<tr class="p-searchable" data-search="${esc(Object.entries(r).filter(([k])=>!['passwordHash','salt'].includes(k)).map(([,v])=>v).join(' '))}" data-filter="${r.active?'Active':'Inactive'}">${cells.map(c=>`<td>${c}</td>`).join('')}</tr>`}
 function management(type){const cfg=configs[type];if(!cfg)return heading('Page not found.','Choose a section from the sidebar.');return heading(cfg.label, cfg.desc,btn('+ Add '+cfg.singular,'add',`data-type="${type}"`))+toolbar('Search '+cfg.label.toLowerCase(),[['Active','Active'],['Inactive','Inactive']])+table(cfg.columns,S.db[type].map(r=>recordRow(type,r)))+`<div id="p-no-results" hidden>${empty('No records found.','Try another search or add your first record.')}</div><p class="p-table-foot">${S.db[type].length} records · All edits are saved only in this browser. Deleting referenced records is prevented.</p>`}
 function requestRow(e){const i=S.db.instances.find(x=>x.id===e.instanceId),u=S.db.users.find(u=>u.id===e.userId);return `<tr class="p-searchable" data-search="${esc(u?.name+' '+u?.email+' '+name('courses',i?.courseId)+' '+i?.name)}" data-filter="${e.status}"><td><strong>${esc(u?.name)}</strong><small>${esc(u?.email)}</small></td><td><strong>${esc(name('courses',i?.courseId))}</strong><small>${esc(i?.name)}</small></td><td>${fmtDate(e.created)}</td><td>${status(e.status)}</td><td>${e.status==='Pending'?`<div class="p-row-actions"><button class="p-link" data-action="approve" data-id="${esc(e.id)}">Approve</button><button class="p-link p-delete" data-action="reject" data-id="${esc(e.id)}">Reject</button></div>`:`<button class="p-link" data-action="request-details" data-id="${esc(e.id)}">View decision →</button>`}</td></tr>`}
 function requests(){return heading('Every request, considered.','Review student requests for a specific cohort. Approval checks availability and seat capacity.')+toolbar('Search learners or courses',[['Pending','Pending'],['Approved','Approved'],['Rejected','Rejected']])+table(['Learner','Course instance','Requested','Status','Review'],S.db.enrollments.map(requestRow))+`<div id="p-no-results" hidden>${empty('No requests in this view.','Requests will appear here when a student asks to join a cohort.')}</div>`}
 function capacityOverview(){const instances=S.db.instances.filter(i=>i.active&&i.status==='Open').map(i=>({...i,approved:S.db.enrollments.filter(e=>e.instanceId===i.id&&e.status==='Approved').length,pending:S.db.enrollments.filter(e=>e.instanceId===i.id&&e.status==='Pending').length})).sort((a,b)=>b.approved/b.capacity-a.approved/a.capacity||a.date.localeCompare(b.date)).slice(0,3);return '<p class="p-capacity-intro">Monitor approved places and outstanding requests for open cohorts.</p>'+ (instances.length?instances.map(i=>`<div class="p-capacity-item"><a href="#admin/instances">${esc(i.name)}</a><p>${fmtDate(i.date)} &middot; ${i.pending} pending ${i.pending===1?'request':'requests'}</p><div class="p-progress" role="progressbar" aria-label="${esc(i.name)} approved seats" aria-valuenow="${i.approved}" aria-valuemin="0" aria-valuemax="${i.capacity}"><span style="width:${Math.min(100,Math.round(i.approved/i.capacity*100))}%"></span></div><small>${i.approved} / ${i.capacity} places filled &middot; ${Math.max(0,i.capacity-i.approved)} available</small></div>`).join(''):empty('No open cohorts.','Create or open a course instance to monitor its available places.'))}
 function attention(){const day=864e5,now=Date.now(),live=S.db.instances.filter(i=>i.active&&['Open','Upcoming'].includes(i.status)),pend=S.db.enrollments.filter(e=>e.status==='Pending'),approved=id=>S.db.enrollments.filter(e=>e.instanceId===id&&e.status==='Approved').length,soon=live.filter(i=>!i.teacherId&&(new Date(i.date)-now)<14*day),full=live.filter(i=>approved(i.id)>=i.capacity&&pend.some(e=>e.instanceId===i.id)),old=pend.filter(e=>now-new Date(e.created)>3*day),idle=S.db.courses.filter(c=>c.active&&!live.some(i=>i.courseId===c.id)),items=[[soon,'high','Cohorts starting without a teacher','Starting within 14 days with no instructor assigned','#admin/instances','Assign'],[full,'high','Full cohorts with waiting requests','No seats left to approve these learners. Add capacity or open another cohort','#admin/instances','Review'],[old,'mid','Requests waiting over 3 days','Learners are still waiting for a decision','#admin/requests','Review'],[idle,'low','Courses with no scheduled cohort','Active in the catalog, but students cannot enroll yet','#admin/courses','Schedule']].filter(x=>x[0].length);return items.length?'<div class="p-attention">'+items.map(([list,lvl,t,d,href,cta])=>`<a class="p-attention-item ${lvl}" href="${href}"><span class="p-attention-count">${list.length}</span><div><strong>${t}</strong><small>${d}${list.length<=3?': '+list.map(x=>esc(x.name||x.title||name('courses',S.db.instances.find(i=>i.id===x.instanceId)?.courseId))).join(', '):''}</small></div><span class="p-attention-cta">${cta} &rarr;</span></a>`).join('')+'</div>':empty('Everything is in order.','No unassigned cohorts, full classes or overdue requests right now.')}
 function adminDashboard(){const pending=S.db.enrollments.filter(e=>e.status==='Pending');return heading('A clear view of your center.','Manage the catalog, people and course requests from one workspace.',go('Review requests','#admin/requests'))+stats([['Active courses',S.db.courses.filter(c=>c.active).length,'Across your catalog'],['Open instances',S.db.instances.filter(i=>i.status==='Open'&&i.active).length,'Scheduled cohorts'],['Pending requests',pending.length,'Ready for your review'],['Registered users',S.db.users.length,'Students, teachers & admins']])+panel('Awaiting your review',pending.length?table(['Learner','Course instance','Requested','Status','Review'],pending.slice(0,4).map(requestRow)):empty('You are all caught up.','There are no pending enrollment requests.'),'<a class="p-link" href="#admin/requests">All requests →</a>')+`<div class="p-grid">${panel('Needs your attention',attention())}${panel('Cohort capacity',capacityOverview(),'<a class="p-link" href="#admin/instances">Manage &rarr;</a>')}</div>`}
 function userDetail(id){const u=S.db.users.find(x=>x.id===id);if(!u)return heading('User not found.','This account may have been removed.');const labels={name:'Full name',email:'Email',phone:'Phone',role:'Role',created:'Joined',entityStatus:'Entity status (stored)',college:'College',department:'Department',graduation:'Graduation status',sector:'Company sector',position:'Position',seniority:'Seniority',interests:'Learning interests',about:'About',profilePic:'Profile photo URL',cv:'CV link'};return heading(esc(u.name),'Account details and the profile information supplied by this user.',btn('Edit account','edit',`data-type="users" data-id="${esc(u.id)}"`))+detailCard('User profile',[{label:'Account status',value:u.active?'Active':'Inactive'},...Object.entries(labels).map(([k,label])=>({label,value:k==='created'?fmtDate(u[k]):u[k]||'Not provided',wide:['about','interests'].includes(k),url:['profilePic','cv'].includes(k)}))])+`<p class="p-note">Profile completion fields are optional. No identity-document review or verification workflow is simulated.</p>`+panel('Enrollment history',S.db.enrollments.filter(e=>e.userId===id).map(enrollmentLine).join('')||empty('No enrollment history.','Requests will appear here when this student joins a course.'))}

 function applyFilter(){const search=document.getElementById('p-search'),sel=document.getElementById('p-filter');if(!search)return;query=search.value;filter=sel?.value||'';let count=0;root.querySelectorAll('.p-searchable').forEach(r=>{const matches=r.dataset.search.toLowerCase().includes(query.toLowerCase().trim())&&(!filter||filter===r.dataset.filter);r.hidden=!matches;if(matches)count++});const no=document.getElementById('p-no-results');if(no)no.hidden=count>0;const countEl=document.getElementById('p-count');if(countEl)countEl.textContent=count+' '+(count===1?'result':'results')}
 function routeURL(route){const base=route.split('?')[0],pages={login:'login.html',signup:'signup.html',profile:'profile.html',favorites:'saved-courses.html','my-courses':'my-courses.html',teaching:'teaching.html',recommendations:'recommendations.html',catalog:'courses.html',notifications:'profile.html',settings:'settings.html',dashboard:'index.html'};if(base.startsWith('admin'))return 'workspace.html#'+route;if(base.startsWith('course/'))return 'course-instances.html#'+route;if(base.startsWith('teacher/'))return 'teacher-profile.html#'+route;return (pages[base]||'profile.html')+(route.includes('?')?'#'+route:'')}
 function memberLinks(){root.querySelectorAll('a[href^="#"]').forEach(a=>a.setAttribute('href',routeURL(a.getAttribute('href').slice(1))))}
 function finishLogin(){const next=sessionStorage.getItem('titanium-next-route');sessionStorage.removeItem('titanium-next-route');const admin=S.user()?.role==='Admin';location.href=admin?'workspace.html#admin':next&&!next.startsWith('workspace.html#admin')?next:'index.html'}
 function render(){S.refresh();let route;try{route=decodeURIComponent(location.hash.slice(1)||document.getElementById('workspace').dataset.initial||(S.user()?.role==='Admin'?'admin':'dashboard'))}catch{route='profile'}const base=route.split('?')[0],u=S.user();if(current!==base){query='';filter=''}current=base;document.getElementById('workspace').dataset.mode=['login','signup'].includes(base)?'auth':u?.role==='Admin'?'admin':'member';window.TitaniumMemberNav?.sync();
  if(base==='dashboard'){location.replace(u?.role==='Admin'?'workspace.html#admin':'index.html');return}
  if(base==='catalog'){location.replace('courses.html');return}
  if(!u&&!['login','signup'].includes(base)){sessionStorage.setItem('titanium-next-route',routeURL(route));location.replace('login.html');return}
  if(['login','signup'].includes(base)){root.innerHTML=auth(base==='signup');memberLinks();return}
  if(base.startsWith('admin')&&u.role!=='Admin'){root.innerHTML=shell(heading('Admin access required.','This area is reserved for training center administration.',go('Back to website','index.html','secondary')));return}
  if(['my-courses','favorites','recommendations'].includes(base)&&u.role==='Admin'){root.innerHTML=shell(heading('Your admin account.','Use a Student or Teacher account to review personal learning features.',go('Admin dashboard','workspace.html#admin','secondary')));return}
  let content;if(base==='admin')content=adminDashboard();else if(base==='admin/requests')content=requests();else if(base.startsWith('admin/user/'))content=userDetail(base.split('/')[2]);else if(base==='admin/profile')content=profile();else if(base.startsWith('admin/course/'))content=courseEditor(base.slice(13));else if(base.startsWith('admin/'))content=management(base.split('/')[1]);else if(base==='favorites')content=catalog(true);else if(base.startsWith('course/'))content=courseDetail(base.split('/')[1]);else if(base.startsWith('teacher/'))content=teacherProfile(base.split('/')[1]);else if(base==='my-courses')content=myCourses();else if(base==='profile'||base==='notifications')content=profile();else if(base==='settings')content=settingsPage();else if(base==='recommendations')content=heading('Recommended for your next chapter.','Explore a few courses to inspire your next step.')+recommendations();else if(base==='teaching'&&u.role==='Teacher')content=teaching();else content=heading('Choose your next step.','This page could not be found.',go('Back to website','index.html'));
  if(base==='profile'&&u.role!=='Admin')content='<nav class="p-profile-tabs" aria-label="Your account"><a href="profile.html" aria-current="page">My profile</a><a href="my-courses.html">My courses</a><a href="saved-courses.html">Saved courses</a></nav>'+content;
  if(base==='my-courses')content+=panel('Recommended for you',recommendations());
  root.innerHTML=shell(content);memberLinks();mountEditor();window.TitaniumAdminSidebar?.mount(root.querySelector('.p-sidebar'));adminTree();applyFilter();root.querySelector('h1')?.focus({preventScroll:true});if(base==='notifications')document.getElementById('notification-toggle')?.click();
 }
 function openModal(title,body,options={}){dialog.classList.remove('p-record-dialog');dialog.classList.toggle('p-edit-dialog',title.startsWith('Edit '));modalReturn=document.activeElement;dialog.innerHTML=`<div class="p-dialog-head"><h2 id="portal-dialog-title">${title}</h2><button type="button" class="p-close" data-action="close" aria-label="Close dialog">×</button></div>${body}`;window.TitaniumModal?.prepare(dialog,{icon:/delete/i.test(title)?'delete':'record',description:/details/i.test(title)?'Review the information for this record.':/^(Add|Edit)/.test(title)?'Update the details below, then save your changes.':undefined,...options});dialog.showModal()}
 function close(){dialog.close();modalReturn?.isConnected&&modalReturn.focus()}
 function edit(type,id){const cfg=configs[type],old=S.db[type].find(r=>r.id===id),r=old||{active:true,discount:0,price:0,capacity:20,status:'Open',currency:'IQD',lectures:1,difficulty:'Beginner',language:'English'};if(!cfg)return;const fields=cfg.fields.map(([key,label,kind,required,options])=>{let hint='';if(kind==='password')hint=old?'Leave blank to keep the current password.':'Required for a new account; at least 8 characters.';if(kind==='teacherUsers'){options=S.db.users.filter(u=>u.role==='Teacher'&&(u.active||u.id===r.userId)).map(u=>[u.id,u.name+' · '+u.email]);hint='Create a Teacher role account in Users first.';kind='select'}else if(S.db[kind]){options=S.db[kind].filter(x=>x.active||x.id===r[key]).map(x=>[x.id,x.name||x.title]);kind='select'}return field(key,label,kind,r[key]??'',required||(key==='password'&&!old),hint,options)}).join('');openModal((old?'Edit ':'Add ')+cfg.singular,`<form id="record-form" data-type="${type}" data-id="${esc(id||'')}"><div class="p-fields">${fields}</div><p class="p-error" id="record-error" role="alert" hidden></p><div class="p-form-actions">${btn('Cancel','close','','secondary')}<button class="p-btn" type="submit">Save ${cfg.singular}</button></div></form>`)}
 function detailCard(title,fields,embedded=false){const normal=fields.filter(f=>!f.wide),wide=fields.filter(f=>f.wide);if(normal.length%2)normal[normal.length-1]={...normal.at(-1),wide:true};fields=[...normal,...wide];const grid=`<dl class="p-record-grid">${fields.map(({label,value,wide=false,url=false})=>`<div class="p-record-cell${wide?' full':''}"><dt>${esc(label)}</dt><dd>${url&&safeHref(value)?`<a href="${safeHref(value)}" target="_blank" rel="noopener noreferrer">${esc(value)}</a>`:esc(value===0?'0':value||'Not set')}</dd></div>`).join('')}</dl>`;return embedded?grid:`<section class="p-record-card"><h3 class="p-record-card-heading">${esc(title)}</h3>${grid}</section>`}
 function view(type,id){const r=S.db[type].find(r=>r.id===id);if(!r)return;const cfg=configs[type],fields=cfg.fields.filter(([k])=>!['password',type==='courses'?'title':'name'].includes(k)).map(([k,label,kind])=>{let value=r[k];if(S.db[kind])value=name(kind,value);if(kind==='teacherUsers')value=name('users',value);if(kind==='checkbox')value=k==='active'?(value?'Active':'Inactive'):(value?'Yes':'No');return {label,value,wide:kind==='textarea',url:kind==='url'}});if(type==='instances')fields.push({label:'Authorized by',value:name('users',r.authorizedBy)},{label:'Authorized date',value:fmtDate(r.authorizedDate)});openModal(esc(type==='courses'?r.title:r.name),detailCard('',fields,true)+`<div class="p-form-actions">${btn('Close','close','','secondary')}</div>`,{description:cfg.singular[0].toUpperCase()+cfg.singular.slice(1)+' details'});dialog.classList.add('p-record-dialog')}

 // Course editor: a full page laid out like the public course page, with every part editable.
 let editorDirty=false;
 const videoEmpty=()=>'<div class="ce-video-empty"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="2.5" y="5" width="19" height="14" rx="3"/><path d="m10 9.5 5 2.5-5 2.5z"/></svg><strong>No video yet</strong><span>Paste a link below to preview it here.</span></div>';
 const videoHint=v=>{if(!v)return 'YouTube and Vimeo links play inside the course page. Direct .mp4 links work too.';const m=S.media.video(v);return m?'Plays as a '+m.label+(m.kind==='iframe'?' embed':'')+' on the course page.':'Use a full https:// link.'};
 const thumbHint=()=> 'Landscape 16:9 works best, at least 1280 × 720.';
 const tick='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m5 12.5 4.2 4.2L19 7"/></svg>';
 const outcomeRow=text=>'<li class="ce-outcome"><span class="ce-tick">'+tick+'</span><input type="text" maxlength="240" value="'+esc(text)+'" aria-label="Learning point" placeholder="A practical skill learners gain"><button type="button" class="ce-remove" data-ce-remove-outcome aria-label="Remove this point"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 6l12 12M18 6 6 18"/></svg></button></li>';
 function editorCard(c){const cat=name('categories',c.categoryId),mark=S.mark(c.id)||'';return '<article class="course-card has-thumb" aria-label="Course card preview"><div class="course-thumb" data-cover-mark="'+esc(mark)+'">'+S.media.poster(c,mark)+'<div class="course-top"><span class="subject">'+esc(cat==='—'?'Category':cat)+'</span></div></div><div class="course-identity"><div class="course-code">'+esc(c.short||'Short name')+'</div></div><h3>'+esc(c.title||'Course title')+'</h3><p>'+esc(c.description||'A short description appears here.')+'</p><div class="course-bottom"><a class="course-button" tabindex="-1" aria-hidden="true">Explore course →</a></div></article>'}
 function courseEditor(id){
  const isNew=id==='new',c=isNew?{title:'',short:'',description:'',lectures:1,difficulty:'Beginner',language:'English',active:true,video:'',thumbnail:'',categoryId:'',vendorId:'',certificateId:''}:S.db.courses.find(c=>c.id===id);
  if(!c)return heading('Course not found.','This course may have been deleted.',go('All courses','#admin/courses','secondary'));
  const opts=(table,value)=>S.db[table].filter(x=>x.active||x.id===value).map(x=>[x.id,x.name||x.title]);
  const cohorts=isNew?[]:S.db.instances.filter(i=>i.courseId===c.id),open=cohorts.filter(i=>i.active&&i.status==='Open').length;
  const pending=S.db.enrollments.filter(e=>e.status==='Pending'&&cohorts.some(i=>i.id===e.instanceId)).length;
  const page=isNew?'':c.publicPage||'course-instances.html#course/'+encodeURIComponent(c.id),mark=S.mark(c.id)||'',cat=name('categories',c.categoryId),uploaded=/^data:/.test(c.thumbnail||'');
  return `<form id="course-editor" class="ce" data-id="${esc(isNew?'':c.id)}" novalidate>
  <div class="ce-bar"><nav class="ce-crumbs" aria-label="Breadcrumb"><a href="#admin/courses">Courses</a><span aria-hidden="true">/</span><span aria-current="page" data-ce-crumb>${esc(c.short||'New course')}</span></nav><span class="ce-state" data-ce-state role="status">${isNew?'Not saved yet':'All changes saved'}</span><div class="ce-actions">${page?`<a class="p-btn secondary" href="${esc(page)}" target="_blank" rel="noopener">View page ↗</a>`:''}<a class="p-btn secondary" href="#admin/courses">Cancel</a><button class="p-btn" type="submit">${isNew?'Create course':'Save changes'}</button></div></div>
  <p class="p-error ce-error" id="course-error" role="alert" hidden></p>
  <div class="ce-layout"><div class="ce-main">
   <section class="ce-hero" aria-label="Course heading">
    <span class="ce-kicker" data-ce-kicker>${esc(cat==='—'?'Choose a category':cat)}</span>
    <label class="ce-hidden-label" for="ce-title">Course title</label><textarea id="ce-title" class="ce-title" name="title" rows="1" maxlength="140" placeholder="Course title">${esc(c.title)}</textarea>
    <label class="ce-hidden-label" for="ce-lead">Introduction</label><textarea id="ce-lead" class="ce-lead" name="overview" rows="2" maxlength="3000" placeholder="The introduction shown under the course title: what the course covers and why it matters.">${esc(c.overview||'')}</textarea>
    <div class="ce-facts p-fields">${field('short','Short name','text',c.short,true)}${field('lectures','Lectures','number',c.lectures,true)}${field('difficulty','Difficulty','select',c.difficulty,false,'',['Beginner','Intermediate','Advanced'])}${field('language','Language','select',c.language,false,'',['English','Arabic','English & Arabic'])}</div>
   </section>
   <section class="ce-section" aria-labelledby="ce-media-title"><div class="ce-section-head"><h2 id="ce-media-title">Thumbnail &amp; video.</h2><p>The thumbnail appears on course cards and the course page. The video plays inside the course page.</p></div>
    <div class="ce-media">
     <div class="ce-media-item"><h3>Thumbnail</h3><div class="ce-thumb" data-ce-thumb data-cover-mark="${esc(mark)}">${S.media.poster(c,mark)}</div>
      <input type="hidden" name="thumbnail" value="${esc(c.thumbnail||'')}">
      <div class="ce-media-actions"><label class="p-btn secondary ce-upload">Upload image<input type="file" accept="image/png,image/jpeg,image/webp" data-ce-upload></label><button type="button" class="p-btn secondary" data-ce-clear-thumb${c.thumbnail?'':' hidden'}>Remove</button></div>
      <div class="p-field"><label for="ce-thumb-url">Or paste an image link</label><input id="ce-thumb-url" type="url" inputmode="url" placeholder="https://…" value="${esc(uploaded?'':c.thumbnail||'')}" data-ce-thumb-url aria-describedby="ce-thumb-hint"><small id="ce-thumb-hint" data-ce-thumb-hint>${uploaded?'Using an uploaded image saved in this browser.':thumbHint()}</small></div></div>
     <div class="ce-media-item"><h3>Preview video</h3><div class="ce-video" data-ce-video>${S.media.player(c,mark)||videoEmpty()}</div>
      <div class="p-field"><label for="p-video">Video link</label><input id="p-video" name="video" type="url" inputmode="url" placeholder="YouTube, Vimeo or an .mp4 link" value="${esc(c.video||'')}" aria-describedby="ce-video-hint"><small id="ce-video-hint" data-ce-video-hint>${videoHint(c.video)}</small></div></div>
    </div></section>
   <section class="ce-section"><div class="ce-section-head"><h2>Card description.</h2><p>One or two sentences shown on course cards across the website.</p></div><textarea class="ce-text" name="description" rows="2" maxlength="400" aria-label="Card description" placeholder="A short summary for course cards.">${esc(c.description)}</textarea></section>
   <section class="ce-section"><div class="ce-section-head"><h2>Who it’s for.</h2><p>Help learners decide if the course is right for them.</p></div><textarea class="ce-text" name="audience" rows="3" maxlength="3000" aria-label="Who it’s for" placeholder="The roles, experience or goals this course suits.">${esc(c.audience||'')}</textarea></section>
   <section class="ce-section"><div class="ce-section-head"><h2>Learning experience.</h2><p>Short points shown as a checklist, up to 15. Press Enter to add another.</p></div><ul class="ce-outcomes" data-ce-outcomes>${(c.outcomes||[]).map(outcomeRow).join('')}</ul><button type="button" class="p-btn secondary ce-add" data-ce-add-outcome>+ Add a point</button></section>
  </div>
  <aside class="ce-side">
   <div class="ce-panel"><h2>Card preview</h2><div class="ce-card" data-ce-card>${editorCard(c)}</div></div>
   <div class="ce-panel"><h2>Publishing</h2>${field('active','Visible on the website','checkbox',c.active!==false)}<div class="p-fields ce-side-fields">${field('categoryId','Category','select',c.categoryId,false,'',opts('categories',c.categoryId))}${field('vendorId','Vendor','select',c.vendorId,false,'',opts('vendors',c.vendorId))}${field('certificateId','Certificate','select',c.certificateId,false,'',opts('certificates',c.certificateId))}</div></div>
   ${isNew?'':`<div class="ce-panel"><h2>Cohorts</h2><p class="ce-stat"><strong>${cohorts.length}</strong> scheduled · ${open} open${pending?` · <span class="ce-pending">${pending} pending</span>`:''}</p><a class="p-link" href="#admin/instances">Manage course instances →</a></div>
   <div class="ce-panel ce-danger"><h2>Delete course</h2><p>Removes it from the catalog. Courses with cohorts can’t be deleted.</p><button type="button" class="p-link p-delete" data-action="delete" data-type="courses" data-id="${esc(c.id)}">Delete this course</button></div>`}
  </aside></div></form>`}
 async function shrinkImage(file){
  if(!/^image\/(png|jpeg|webp)$/.test(file.type))throw Error('Choose a PNG, JPEG or WebP image.');
  if(file.size>20e6)throw Error('Choose an image under 20 MB.');
  const bmp=await createImageBitmap(file),scale=Math.min(1,1280/bmp.width,1280/bmp.height),canvas=document.createElement('canvas');
  canvas.width=Math.round(bmp.width*scale);canvas.height=Math.round(bmp.height*scale);const g=canvas.getContext('2d');g.fillStyle='#fff';g.fillRect(0,0,canvas.width,canvas.height);g.drawImage(bmp,0,0,canvas.width,canvas.height);bmp.close?.();
  for(const q of [.85,.75,.62,.5]){const url=canvas.toDataURL('image/jpeg',q);if(url.length<900000)return url}
  throw Error('That image is too large to store in this browser. Try a smaller one.')}
 function mountEditor(){
  const form=document.getElementById('course-editor');if(!form)return;editorDirty=false;
  const id=form.dataset.id,c=S.db.courses.find(x=>x.id===id)||{},$=s=>form.querySelector(s),thumb=form.elements.thumbnail,mark=S.mark(id)||'';
  const autosize=el=>{el.style.height='auto';el.style.height=el.scrollHeight+2+'px'};
  form.querySelectorAll('.ce-title,.ce-lead,.ce-text').forEach(el=>{autosize(el);el.addEventListener('input',()=>autosize(el))});
  const draft=()=>({id,title:form.elements.title.value.trim(),short:form.elements.short.value.trim(),description:form.elements.description.value.trim(),categoryId:form.elements.categoryId.value,thumbnail:thumb.value,video:form.elements.video.value.trim()});
  const refresh=()=>{const d=draft(),cat=name('categories',d.categoryId);$('[data-ce-card]').innerHTML=editorCard(d);$('[data-ce-thumb]').innerHTML=S.media.poster(d,mark);$('[data-ce-crumb]').textContent=d.short||'New course';$('[data-ce-kicker]').textContent=cat==='—'?'Choose a category':cat;$('[data-ce-clear-thumb]').hidden=!d.thumbnail};
  let videoTimer;const refreshVideo=()=>{clearTimeout(videoTimer);videoTimer=setTimeout(()=>{const d=draft();$('[data-ce-video]').innerHTML=S.media.player(d,mark)||videoEmpty();$('[data-ce-video-hint]').textContent=videoHint(d.video)},300)};
  const dirty=()=>{editorDirty=true;const s=$('[data-ce-state]');s.textContent='Unsaved changes';s.classList.add('is-dirty')};
  form.addEventListener('input',e=>{if(e.target.type==='file')return;dirty();if(e.target.name==='video')return refreshVideo();if(e.target.matches('[data-ce-thumb-url]')){const v=e.target.value.trim();thumb.value=v;$('[data-ce-thumb-hint]').textContent=v&&!S.media.imageURL(v)?'Use a full https:// image link.':thumbHint()}refresh()});
  $('[data-ce-upload]').addEventListener('change',async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{thumb.value=await shrinkImage(file);$('[data-ce-thumb-url]').value='';$('[data-ce-thumb-hint]').textContent='Using an uploaded image saved in this browser.';dirty();refresh()}catch(err){toast(err.message)}});
  form.addEventListener('click',e=>{
   if(e.target.closest('[data-ce-clear-thumb]')){thumb.value='';$('[data-ce-thumb-url]').value='';$('[data-ce-thumb-hint]').textContent=thumbHint();dirty();refresh();$('.ce-upload').focus?.()}
   if(e.target.closest('[data-ce-add-outcome]')){const list=$('[data-ce-outcomes]');if(list.children.length>=15){toast('Use up to 15 points.');return}list.insertAdjacentHTML('beforeend',outcomeRow(''));list.lastElementChild.querySelector('input').focus();dirty()}
   const rm=e.target.closest('[data-ce-remove-outcome]');if(rm){const li=rm.closest('li'),next=li.nextElementSibling||li.previousElementSibling;li.remove();(next?.querySelector('input')||$('[data-ce-add-outcome]')).focus();dirty()}});
  form.addEventListener('keydown',e=>{if(e.key!=='Enter')return;if(e.target.matches('.ce-outcome input')){e.preventDefault();$('[data-ce-add-outcome]').click()}else if(e.target.matches('.ce-title'))e.preventDefault()});
  // Built-in courses keep their page text in the HTML; load it so editing starts from what visitors see.
  if(c.publicPage&&[c.overview,c.audience,c.outcomes].includes(undefined))fetch(c.publicPage).then(r=>r.ok?r.text():'').then(html=>{if(!html||!form.isConnected)return;const doc=new DOMParser().parseFromString(html,'text/html');
   for(const [key,sel] of [['overview','.course-lead'],['audience','#audience p']]){const el=form.elements[key];if(c[key]===undefined&&!el.value){el.value=doc.querySelector(sel)?.textContent.trim()||'';autosize(el)}}
   const list=$('[data-ce-outcomes]');if(c.outcomes===undefined&&!list.children.length)list.innerHTML=[...doc.querySelectorAll('#learning .check-list li')].map(li=>outcomeRow(li.textContent.trim())).join('')}).catch(()=>{});
 }

 function error(formId,message){const el=document.getElementById(formId);if(el){el.hidden=false;el.textContent=message}else toast(message)}
 root.addEventListener('input',e=>{if(e.target.id==='p-search')applyFilter()});root.addEventListener('change',e=>{if(e.target.id==='p-filter')applyFilter()});
 document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const {action,id,type,role}=b.dataset;try{
  if(action==='close')close();if(action==='menu'){const side=root.querySelector('.p-sidebar');side.classList.toggle('is-open');b.setAttribute('aria-expanded',String(side.classList.contains('is-open')))}
  if(action==='demo'){S.demo(role);finishLogin()}
  if(action==='logout'){S.logout();location.href='login.html'}
  if(action==='favorite'){S.favorite(id);render();toast('Saved courses updated.')}
  if(action==='request'){const i=S.db.instances.find(i=>i.id===id);openModal('Request your place.',`<p>You are requesting to join <strong>${esc(i.name)}</strong> for ${esc(name('courses',i.courseId))}.</p><p>An administrator will review your request. You can follow the decision in My courses. No payment is collected.</p><div class="p-form-actions">${btn('Cancel','close','','secondary')}${btn('Send request','confirm-request',`data-id="${esc(id)}"`)}</div>`)}
  if(action==='confirm-request'){S.request(id);close();render();toast('Request sent. You can track it in My courses.')}
  if((action==='add'||action==='edit')&&type==='courses'){location.hash='admin/course/'+(id?encodeURIComponent(id):'new');return}if(action==='add'||action==='edit')edit(type,id);if(action==='view')view(type,id);
  if(action==='delete'){const r=S.db[type].find(r=>r.id===id);openModal('Delete this record?',`<p><strong>${esc(r.title||r.name)}</strong> will be removed from this browser. Referenced records cannot be deleted.</p><p class="p-error" id="delete-error" role="alert" hidden></p><div class="p-form-actions">${btn('Keep record','close','','secondary')}${btn('Delete record','confirm-delete',`data-type="${type}" data-id="${esc(id)}"`,'danger')}</div>`)}
  if(action==='confirm-delete'){try{S.remove(type,id);close();if(current.startsWith('admin/course/')){editorDirty=false;location.hash='admin/courses'}else render();toast('Record deleted.')}catch(err){error('delete-error',err.message)}}
  if(action==='approve'||action==='reject'){const enrollment=S.db.enrollments.find(e=>e.id===id),i=S.db.instances.find(i=>i.id===enrollment.instanceId);openModal(action==='approve'?'Approve this request?':'Reject this request?',`<p>${esc(name('users',enrollment.userId))} · ${esc(i.name)}</p><form id="decision-form" data-id="${esc(id)}" data-status="${action==='approve'?'Approved':'Rejected'}">${action==='reject'?field('reason','Reason shown to the student','textarea','',true):'<p>Approval adds this learner to the cohort and uses one available seat.</p>'}<p class="p-error" id="decision-error" role="alert" hidden></p><div class="p-form-actions">${btn('Cancel','close','','secondary')}<button class="p-btn" type="submit">${action==='approve'?'Approve request':'Reject request'}</button></div></form>`)}
  if(action==='request-details'){const r=S.db.enrollments.find(e=>e.id===id);openModal('Enrollment decision',`${status(r.status)}<dl class="p-facts"><div><dt>Reviewed by</dt><dd>${esc(name('users',r.reviewer))}</dd></div><div><dt>Reviewed on</dt><dd>${fmtDate(r.reviewed)}</dd></div></dl><p>${esc(r.reason||'This request was approved.')}</p>`)}
 }catch(err){toast(err.message)}});
 document.addEventListener('submit',async e=>{const form=e.target;if(!['auth-form','profile-form','record-form','decision-form','course-editor'].includes(form.id))return;e.preventDefault();const values=Object.fromEntries(new FormData(form)),submit=form.querySelector('[type=submit]')||dialog.querySelector('[type=submit][form="'+form.id+'"]');submit.disabled=true;try{
  if(form.id==='auth-form'){if(form.dataset.mode==='signup'){if(values.password!==values.confirmPassword)throw Error('The passwords do not match.');await S.signup(values)}else await S.login(values.email,values.password);finishLogin()}
  if(form.id==='profile-form'){S.profile(values);render();toast('Your profile is saved.')}
  if(form.id==='record-form'){const type=form.dataset.type,id=form.dataset.id,r={...values};if(id)r.id=id;for(const [key,,kind] of configs[type].fields){if(kind==='checkbox')r[key]=form.elements[key].checked;if(kind==='number')r[key]=Number(values[key]||0)}if(type==='users'){if(values.password)Object.assign(r,await S.password(values.password));if(!id)r.demo=false}delete r.password;S.saveRecord(type,r);close();render();toast('Record saved.')}
  if(form.id==='course-editor'){const id=form.dataset.id,r={title:values.title.trim(),short:values.short.trim(),description:values.description.trim(),lectures:Number(values.lectures||0),difficulty:values.difficulty,language:values.language,categoryId:values.categoryId,vendorId:values.vendorId,certificateId:values.certificateId,video:values.video.trim(),thumbnail:values.thumbnail,overview:values.overview,audience:values.audience,outcomes:[...form.querySelectorAll('.ce-outcome input')].map(i=>i.value),active:form.elements.active.checked};if(id)r.id=id;const saved=S.saveRecord('courses',r);editorDirty=false;toast(id?'Course saved.':'Course created.');if(id)render();else location.hash='admin/course/'+encodeURIComponent(saved.id)}
  if(form.id==='decision-form'){S.decide(form.dataset.id,form.dataset.status,values.reason||'');close();render();toast('Enrollment decision saved.')}
 }catch(err){const errorIds={'course-editor':'course-error','auth-form':'auth-error','profile-form':'profile-error','record-form':'record-error','decision-form':'decision-error'};error(errorIds[form.id],err.message)}finally{submit.disabled=false}});
 dialog.addEventListener('close',()=>modalReturn?.isConnected&&modalReturn.focus());
 document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!dialog.open){const side=root.querySelector('.p-sidebar.is-open');if(side){side.classList.remove('is-open');const toggle=side.querySelector('[data-action=menu]');toggle.setAttribute('aria-expanded','false');toggle.focus()}}});
 let lastHash=location.hash,restoring=false;
 addEventListener('hashchange',()=>{if(restoring){restoring=false;return}if(editorDirty&&!confirm('You have unsaved changes to this course. Leave without saving?')){restoring=true;location.hash=lastHash;return}editorDirty=false;lastHash=location.hash;if(dialog.open)close();render();window.scrollTo(0,0)});
 addEventListener('beforeunload',e=>{if(editorDirty){e.preventDefault();e.returnValue=''}});
 addEventListener('storage',e=>{if([S.KEY,S.SESSION].includes(e.key)&&!editorDirty)render()});render();
})();
